**Plan**
- `CheckpointValidator` keeps one run per player id (any netcode) and exposes `ReportCheckpoint(playerId, index, serverTime)`, called by the server when its own trigger fires; positions come from the `checkpoints` Transforms.
- A skipped index rubber-bands the player to their last checkpoint and adds skips and flags; the time between checkpoints must be at least `(distance - radii) / (maxSpeed x 1.15) - lagSeconds` unless the player has a server-granted exemption (boosts, vehicles, teleports).
- 2+ skips or 3 flags raises `OnBan` with the evidence log; `OnRubberBand` gives the position to move the player to, and `enforce = false` is a shadow mode that only logs.

```csharp
using System;
using System.Collections.Generic;
using UnityEngine;

public class CheckpointValidator : MonoBehaviour
{
    public enum Verdict { Accepted, RejectedSkip, RejectedTooFast, Banned }

    private class Run
    {
        public int Last = -1;
        public double LastTime;
        public int Skips;
        public int Flags;
        public double ExemptUntil;
        public readonly List<string> Log = new List<string>();
    }

    [SerializeField] private Transform[] checkpoints;
    [SerializeField] private float maxSpeed = 7f;
    [SerializeField] private float speedTolerance = 1.15f;
    [SerializeField] private float lagSeconds = 0.3f;
    [SerializeField] private float checkpointRadius = 2f;
    [SerializeField] private int maxSkips = 2;
    [SerializeField] private int maxFlags = 3;
    [SerializeField] private bool enforce = true;

    private readonly Dictionary<ulong, Run> runs = new Dictionary<ulong, Run>();

    public event Action<ulong, Vector3> OnRubberBand;
    public event Action<ulong, string, string> OnBan;

    public void StartRun(ulong playerId, double serverTime)
    {
        runs[playerId] = new Run { LastTime = serverTime };
    }

    // Call from server code that legitimately moves a player (boost pad, vehicle, teleport).
    public void GrantExemption(ulong playerId, double serverTime, double seconds)
    {
        Run run;
        if (runs.TryGetValue(playerId, out run)) run.ExemptUntil = serverTime + seconds;
    }

    public Verdict ReportCheckpoint(ulong playerId, int index, double serverTime)
    {
        Run run;
        if (!runs.TryGetValue(playerId, out run) || index <= run.Last || index >= checkpoints.Length) return Verdict.Accepted;

        int gap = index - run.Last - 1;
        if (gap > 0)
        {
            run.Skips += gap;
            run.Flags++;
            Record(playerId, run, string.Format("SKIP touched {0} after {1} (skipped {2})", index, run.Last, gap));
            if (run.Skips >= maxSkips || run.Flags >= maxFlags) return Ban(playerId, run, "Checkpoint skipping");
            RubberBand(playerId, run.Last);
            return Verdict.RejectedSkip;
        }

        if (run.Last >= 0 && serverTime >= run.ExemptUntil)
        {
            Vector3 from = checkpoints[run.Last].position;
            Vector3 to = checkpoints[index].position;
            float distance = Mathf.Max(0f, Vector3.Distance(from, to) - 2f * checkpointRadius);
            double minTime = distance / (maxSpeed * speedTolerance) - lagSeconds;
            double elapsed = serverTime - run.LastTime;
            if (elapsed < minTime)
            {
                run.Flags++;
                Record(playerId, run, string.Format("TOO_FAST {0}->{1} distance {2:0.0}m in {3:0.00}s, minimum {4:0.00}s", run.Last, index, distance, elapsed, minTime));
                if (run.Flags >= maxFlags) return Ban(playerId, run, "Checkpoint speed");
                RubberBand(playerId, run.Last);
                return Verdict.RejectedTooFast;
            }
        }
        run.Last = index;
        run.LastTime = serverTime;
        return Verdict.Accepted;
    }

    private void RubberBand(ulong playerId, int checkpointIndex)
    {
        if (!enforce || OnRubberBand == null) return;
        OnRubberBand(playerId, checkpoints[Mathf.Max(checkpointIndex, 0)].position);
    }

    private Verdict Ban(ulong playerId, Run run, string reason)
    {
        Record(playerId, run, "BAN " + reason);
        if (enforce && OnBan != null) OnBan(playerId, reason, string.Join(" | ", run.Log.ToArray()));
        return Verdict.Banned;
    }

    private static void Record(ulong playerId, Run run, string message)
    {
        string line = string.Format("[{0:HH:mm:ss}] player {1}: {2}", DateTime.UtcNow, playerId, message);
        run.Log.Add(line);
        Debug.LogWarning("[CheckpointAC] " + line);
    }
}
```

The validator never sees the client: the server calls it from its own physics trigger with its own clock, so it works with any netcode. The first violations rubber-band the player and only repeated or clear ones raise a ban, the minimum time subtracts the checkpoint radii and a lag allowance, and `GrantExemption` is how honest boosts, vehicles and teleports avoid flags.

**Plan**
- `MovementValidator.Submit(playerId, position, serverTime)` takes a timestamped snapshot and returns a `MoveResult` (valid flag, correction position, reason).
- Horizontal speed uses a leaky debt (lag spikes are forgiven, sustained speed is not), vertical speed has separate up and down limits, and any single step beyond `teleportDistance` is rejected outright.
- `AllowTeleport(playerId, target, serverTime)` whitelists a server teleport: the next snapshot near the target is accepted and resets the baseline; valid positions are remembered so rejections return the last valid position.

```csharp
using System.Collections.Generic;
using UnityEngine;

public struct MoveResult
{
    public bool Valid;
    public Vector3 Correction;
    public string Reason;
}

public class MovementValidator : MonoBehaviour
{
    private class Track
    {
        public Vector3 LastPosition;
        public Vector3 ValidPosition;
        public double LastTime;
        public float Debt;
        public bool TeleportPending;
        public Vector3 TeleportTarget;
        public double TeleportExpires;
    }

    [SerializeField] private float maxHorizontalSpeed = 7f;
    [SerializeField] private float maxUpSpeed = 14f;
    [SerializeField] private float maxDownSpeed = 60f;
    [SerializeField] private float speedTolerance = 1.15f;
    [SerializeField] private float slackMetres = 0.75f;
    [SerializeField] private float debtLimit = 3f;
    [SerializeField] private float maxLagCreditSeconds = 1f;
    [SerializeField] private float teleportDistance = 25f;
    [SerializeField] private float teleportMatchRadius = 2f;

    private readonly Dictionary<ulong, Track> tracks = new Dictionary<ulong, Track>();

    public void Remove(ulong playerId) { tracks.Remove(playerId); }

    public void AllowTeleport(ulong playerId, Vector3 target, double serverTime)
    {
        Track track;
        if (!tracks.TryGetValue(playerId, out track)) return;
        track.TeleportPending = true;
        track.TeleportTarget = target;
        track.TeleportExpires = serverTime + 5.0;
    }

    public MoveResult Submit(ulong playerId, Vector3 position, double serverTime)
    {
        Track track;
        if (!tracks.TryGetValue(playerId, out track))
        {
            tracks[playerId] = new Track { LastPosition = position, ValidPosition = position, LastTime = serverTime };
            return new MoveResult { Valid = true, Correction = position };
        }

        if (track.TeleportPending && serverTime <= track.TeleportExpires
            && Vector3.Distance(position, track.TeleportTarget) <= teleportMatchRadius)
        {
            track.TeleportPending = false;
            track.Debt = 0f;
            return Accept(track, position, serverTime);
        }

        float dt = (float)Mathf.Clamp((float)(serverTime - track.LastTime), 0.001f, maxLagCreditSeconds);
        Vector3 delta = position - track.LastPosition;
        float horizontal = new Vector3(delta.x, 0f, delta.z).magnitude;
        float vertical = delta.y;

        if (delta.magnitude > teleportDistance)
            return Reject(track, serverTime, string.Format("teleport {0:0.0}m in {1:0.00}s", delta.magnitude, dt));

        float allowedHorizontal = maxHorizontalSpeed * speedTolerance * dt + slackMetres;
        track.Debt = Mathf.Max(0f, track.Debt + horizontal - allowedHorizontal);
        if (track.Debt > debtLimit)
            return Reject(track, serverTime, string.Format("horizontal {0:0.0}m/s, limit {1:0.0}m/s", horizontal / dt, maxHorizontalSpeed * speedTolerance));

        float verticalLimit = (vertical >= 0f ? maxUpSpeed : maxDownSpeed) * speedTolerance * dt + slackMetres;
        if (Mathf.Abs(vertical) > verticalLimit)
            return Reject(track, serverTime, string.Format("vertical {0:0.0}m/s, limit {1:0.0}m/s", vertical / dt, verticalLimit / dt));

        return Accept(track, position, serverTime);
    }

    private static MoveResult Accept(Track track, Vector3 position, double serverTime)
    {
        track.LastPosition = position;
        track.ValidPosition = position;
        track.LastTime = serverTime;
        return new MoveResult { Valid = true, Correction = position };
    }

    private static MoveResult Reject(Track track, double serverTime, string reason)
    {
        track.LastPosition = track.ValidPosition;
        track.LastTime = serverTime;
        track.Debt = 0f;
        Debug.LogWarning("[MovementValidator] rejected: " + reason);
        return new MoveResult { Valid = false, Correction = track.ValidPosition, Reason = reason };
    }
}
```

The server calls `Submit` for every position update it receives and, when `Valid` is false, snaps the player to `Correction`, so the client's claimed position never becomes the truth. Limits are in metres per second and all of them can be tuned; capping the lag credit stops a long gap between packets from banking unlimited free distance.

**Plan**
- `NoclipDetector.Validate(playerId, from, to, serverTime)` casts a capsule from the last valid position to the new one against `wallMask`, with a small skin so surfaces the player is touching do not count.
- A destination that overlaps a wall (`CheckCapsule`) is also rejected, because casts miss colliders the capsule starts inside.
- A rejection returns the old position as the correction and adds a strike that decays over time; kick and ban events fire at higher counts, and whitelisted server teleports skip the cast.

```csharp
using System;
using System.Collections.Generic;
using UnityEngine;

public class NoclipDetector : MonoBehaviour
{
    private class State
    {
        public float Strikes;
        public double Updated;
        public double TeleportUntil;
    }

    [SerializeField] private LayerMask wallMask = ~0;
    [SerializeField] private float capsuleRadius = 0.35f;
    [SerializeField] private float capsuleHeight = 1.8f;
    [SerializeField] private float skin = 0.05f;
    [SerializeField] private float decayPerMinute = 1f;
    [SerializeField] private float kickStrikes = 6f;
    [SerializeField] private float banStrikes = 10f;
    [SerializeField] private bool enforce = true;

    private readonly Dictionary<ulong, State> states = new Dictionary<ulong, State>();

    public event Action<ulong> OnKick;
    public event Action<ulong, string> OnBan;

    public void AllowTeleport(ulong playerId, double serverTime, double seconds = 1.0)
    {
        GetState(playerId, serverTime).TeleportUntil = serverTime + seconds;
    }

    // Returns the position the server should use. If it differs from "to", move the player back to it.
    public Vector3 Validate(ulong playerId, Vector3 from, Vector3 to, double serverTime)
    {
        State state = GetState(playerId, serverTime);
        if (serverTime <= state.TeleportUntil) return to;

        float radius = Mathf.Max(0.05f, capsuleRadius - skin);
        Vector3 bottom = from + Vector3.up * capsuleRadius;
        Vector3 top = from + Vector3.up * (capsuleHeight - capsuleRadius);
        Vector3 step = to - from;
        float distance = step.magnitude;

        string reason = null;
        RaycastHit hit;
        if (distance > 0.001f && Physics.CapsuleCast(bottom, top, radius, step / distance, out hit, distance, wallMask, QueryTriggerInteraction.Ignore))
            reason = string.Format("passed through '{0}' at {1} (step {2:0.00}m)", hit.collider.name, hit.point, distance);
        else if (Physics.CheckCapsule(to + Vector3.up * capsuleRadius, to + Vector3.up * (capsuleHeight - capsuleRadius), radius, wallMask, QueryTriggerInteraction.Ignore))
            reason = string.Format("ended inside geometry at {0}", to);

        if (reason == null) return to;
        AddStrike(playerId, state, serverTime, string.Format("from {0} to {1}: {2}", from, to, reason));
        return enforce ? from : to;
    }

    private State GetState(ulong playerId, double serverTime)
    {
        State state;
        if (!states.TryGetValue(playerId, out state))
        {
            state = new State { Updated = serverTime };
            states[playerId] = state;
        }
        return state;
    }

    private void AddStrike(ulong playerId, State state, double serverTime, string evidence)
    {
        state.Strikes = Mathf.Max(0f, state.Strikes - (float)(serverTime - state.Updated) / 60f * decayPerMinute) + 1f;
        state.Updated = serverTime;
        Debug.LogWarning(string.Format("[NoclipAC] player {0} strike {1:0.0}: {2}", playerId, state.Strikes, evidence));
        if (!enforce) return;
        if (state.Strikes >= banStrikes && OnBan != null) OnBan(playerId, "Noclip: " + evidence);
        else if (state.Strikes >= kickStrikes && OnKick != null) OnKick(playerId);
    }
}
```

The cast uses the server's own physics scene, so it needs the level's colliders on the server, and a slightly smaller capsule than the real one avoids reporting walls the player is simply standing against. Rejected moves are undone immediately (the first reaction), so only a pattern of strikes can kick or ban.

**Plan**
- `FlyDetector.Validate(playerId, position, velocityY, serverTime)` does a `SphereCast` down from the position to decide if the player is grounded and tracks airborne time, the takeoff height and the height above it.
- Players standing in or on colliders tagged `JumpPad`, `Ladder` or `Water` (checked with `OverlapSphere` and the collider's `tag`) are exempt, and so are server-whitelisted boosts.
- It flags hovering, rising above the maximum jump height, and upward speed above the jump speed; a flag returns the last grounded position as the correction and adds a decaying strike with kick/ban events.

```csharp
using System;
using System.Collections.Generic;
using UnityEngine;

public struct FlyResult
{
    public bool Valid;
    public Vector3 Correction;
}

public class FlyDetector : MonoBehaviour
{
    private class State
    {
        public double AirSince;
        public bool Airborne;
        public Vector3 GroundPosition;
        public float Strikes;
        public double Updated;
        public double ExemptUntil;
    }

    [SerializeField] private LayerMask groundMask = ~0;
    [SerializeField] private string[] exemptTags = { "JumpPad", "Ladder", "Water" };
    [SerializeField] private float groundDistance = 0.6f;
    [SerializeField] private float jumpSpeed = 7f;
    [SerializeField] private float gravity = 9.81f;
    [SerializeField] private float airTolerance = 0.6f;
    [SerializeField] private float heightTolerance = 1.3f;
    [SerializeField] private float decayPerMinute = 1f;
    [SerializeField] private float kickStrikes = 4f;
    [SerializeField] private float banStrikes = 7f;
    [SerializeField] private bool enforce = true;

    private readonly Dictionary<ulong, State> states = new Dictionary<ulong, State>();

    public event Action<ulong> OnKick;
    public event Action<ulong, string> OnBan;

    public void GrantExemption(ulong playerId, double serverTime, double seconds)
    {
        Get(playerId, serverTime, Vector3.zero).ExemptUntil = serverTime + seconds;
    }

    public FlyResult Validate(ulong playerId, Vector3 position, float velocityY, double serverTime)
    {
        State state = Get(playerId, serverTime, position);
        RaycastHit hit;
        bool grounded = Physics.SphereCast(position + Vector3.up * 0.5f, 0.3f, Vector3.down, out hit, 0.5f + groundDistance, groundMask, QueryTriggerInteraction.Ignore);
        if (grounded || serverTime < state.ExemptUntil || InExemptVolume(position))
        {
            state.Airborne = false;
            if (grounded) state.GroundPosition = position;
            return new FlyResult { Valid = true, Correction = position };
        }

        if (!state.Airborne)
        {
            state.Airborne = true;
            state.AirSince = serverTime;
            if (state.GroundPosition == Vector3.zero) state.GroundPosition = position;
        }

        double airTime = serverTime - state.AirSince;
        float height = position.y - state.GroundPosition.y;
        float maxHeight = jumpSpeed * jumpSpeed / (2f * gravity);
        float maxAir = 2f * jumpSpeed / gravity + airTolerance;
        string reason = null;
        if (velocityY > jumpSpeed * 1.25f) reason = string.Format("upward speed {0:0.0} (max {1:0.0})", velocityY, jumpSpeed);
        else if (height > maxHeight * heightTolerance + 0.5f && velocityY > -2f) reason = string.Format("height {0:0.0} (max {1:0.0})", height, maxHeight);
        else if (airTime > maxAir && Mathf.Abs(velocityY) < 1f) reason = string.Format("hovering {0:0.00}s (max {1:0.00}s)", airTime, maxAir);
        if (reason == null) return new FlyResult { Valid = true, Correction = position };

        AddStrike(playerId, state, serverTime, string.Format("{0} at {1}", reason, position));
        state.Airborne = false;
        return new FlyResult { Valid = !enforce, Correction = enforce ? state.GroundPosition : position };
    }

    private bool InExemptVolume(Vector3 position)
    {
        foreach (Collider c in Physics.OverlapSphere(position, 1.2f, ~0, QueryTriggerInteraction.Collide))
            foreach (string tag in exemptTags)
                if (c.gameObject.tag == tag) return true;
        return false;
    }

    private State Get(ulong playerId, double serverTime, Vector3 position)
    {
        State state;
        if (!states.TryGetValue(playerId, out state))
        {
            state = new State { Updated = serverTime, GroundPosition = position };
            states[playerId] = state;
        }
        return state;
    }

    private void AddStrike(ulong playerId, State state, double serverTime, string evidence)
    {
        state.Strikes = Mathf.Max(0f, state.Strikes - (float)(serverTime - state.Updated) / 60f * decayPerMinute) + 1f;
        state.Updated = serverTime;
        Debug.LogWarning(string.Format("[FlyAC] player {0} strike {1:0.0}: {2}", playerId, state.Strikes, evidence));
        if (!enforce) return;
        if (state.Strikes >= banStrikes && OnBan != null) OnBan(playerId, "Fly hack: " + evidence);
        else if (state.Strikes >= kickStrikes && OnKick != null) OnKick(playerId);
    }
}
```

Jump speed and gravity give the maximum jump height and air time, so anything beyond them while not on a pad, ladder or in water is unexplained. Hovering is only flagged when vertical speed is near zero, which keeps legitimate falls, and the first reaction is a move back to the last grounded position. Tags are read from `gameObject.tag` and must exist in the project's Tag Manager to be attached to objects.

**Plan**
- `NetworkMessageGuard.Register(type, ratePerSecond, burst, fields...)` defines each message type with a token-bucket rate and a payload schema (`Int`, `Float`, `String`, `Bool`, `Vector3` fields with min, max or max length).
- `Validate(playerId, type, payload, now)` first spends a token (no token = flooding), then checks the payload has exactly the expected fields with the right types and ranges (no NaN or infinity) and no unknown keys.
- Each failure adds a decaying strike; at `kickStrikes` it raises `OnKick`, and at `banStrikes` `OnBan`, with the offending message and reason as evidence.

```csharp
using System;
using System.Collections.Generic;
using UnityEngine;

public class NetworkMessageGuard : MonoBehaviour
{
    public enum Kind { Int, Float, String, Bool, Vector3 }
    public enum Verdict { Ok, RateLimited, Malformed, Kick, Ban }

    public struct Field
    {
        public string Name;
        public Kind Type;
        public float Min;
        public float Max;
        public int MaxLength;
        public Field(string name, Kind type, float min = float.MinValue, float max = float.MaxValue, int maxLength = 64)
        {
            Name = name; Type = type; Min = min; Max = max; MaxLength = maxLength;
        }
    }

    private class MessageType { public float Rate; public float Burst; public Field[] Fields; }
    private class Bucket { public float Tokens; public double Time; }
    private class Strikes { public float Count; public double Time; }

    [SerializeField] private float kickStrikes = 10f;
    [SerializeField] private float banStrikes = 20f;
    [SerializeField] private float decayPerMinute = 2f;

    private readonly Dictionary<string, MessageType> types = new Dictionary<string, MessageType>();
    private readonly Dictionary<ulong, Dictionary<string, Bucket>> buckets = new Dictionary<ulong, Dictionary<string, Bucket>>();
    private readonly Dictionary<ulong, Strikes> strikes = new Dictionary<ulong, Strikes>();

    public event Action<ulong, string> OnKick;
    public event Action<ulong, string> OnBan;

    public void Register(string type, float ratePerSecond, float burst, params Field[] fields)
    {
        types[type] = new MessageType { Rate = ratePerSecond, Burst = burst, Fields = fields };
    }

    public void RemovePlayer(ulong playerId) { buckets.Remove(playerId); strikes.Remove(playerId); }

    public Verdict Validate(ulong playerId, string type, Dictionary<string, object> payload, double now)
    {
        MessageType message;
        if (!types.TryGetValue(type, out message)) return Punish(playerId, now, "unknown message type " + type);

        Dictionary<string, Bucket> own;
        if (!buckets.TryGetValue(playerId, out own)) { own = new Dictionary<string, Bucket>(); buckets[playerId] = own; }
        Bucket bucket;
        if (!own.TryGetValue(type, out bucket)) { bucket = new Bucket { Tokens = message.Burst, Time = now }; own[type] = bucket; }
        bucket.Tokens = Mathf.Min(message.Burst, bucket.Tokens + (float)(now - bucket.Time) * message.Rate);
        bucket.Time = now;
        if (bucket.Tokens < 1f)
        {
            Verdict v = Punish(playerId, now, "flooding " + type);
            return v == Verdict.Malformed ? Verdict.RateLimited : v;
        }
        bucket.Tokens -= 1f;

        string problem = CheckPayload(message, payload);
        return problem == null ? Verdict.Ok : Punish(playerId, now, type + ": " + problem);
    }

    private static string CheckPayload(MessageType message, Dictionary<string, object> payload)
    {
        if (payload == null || payload.Count != message.Fields.Length) return "wrong field count";
        foreach (Field f in message.Fields)
        {
            object value;
            if (!payload.TryGetValue(f.Name, out value) || value == null) return "missing " + f.Name;
            switch (f.Type)
            {
                case Kind.Int:
                    if (!(value is int) || (int)value < f.Min || (int)value > f.Max) return f.Name + " bad int";
                    break;
                case Kind.Float:
                    if (!(value is float) || float.IsNaN((float)value) || float.IsInfinity((float)value) || (float)value < f.Min || (float)value > f.Max) return f.Name + " bad float";
                    break;
                case Kind.String:
                    if (!(value is string) || ((string)value).Length > f.MaxLength) return f.Name + " bad string";
                    break;
                case Kind.Bool:
                    if (!(value is bool)) return f.Name + " not bool";
                    break;
                case Kind.Vector3:
                    if (!(value is Vector3)) return f.Name + " not vector";
                    Vector3 vec = (Vector3)value;
                    if (float.IsNaN(vec.x + vec.y + vec.z) || vec.sqrMagnitude > f.Max * f.Max) return f.Name + " bad vector";
                    break;
            }
        }
        return null;
    }

    private Verdict Punish(ulong playerId, double now, string reason)
    {
        Strikes s;
        if (!strikes.TryGetValue(playerId, out s)) { s = new Strikes { Time = now }; strikes[playerId] = s; }
        s.Count = Mathf.Max(0f, s.Count - (float)(now - s.Time) / 60f * decayPerMinute) + 1f;
        s.Time = now;
        Debug.LogWarning(string.Format("[MessageGuard] player {0} strike {1:0.0}: {2}", playerId, s.Count, reason));
        if (s.Count >= banStrikes) { if (OnBan != null) OnBan(playerId, reason); return Verdict.Ban; }
        if (s.Count >= kickStrikes) { if (OnKick != null) OnKick(playerId, reason); return Verdict.Kick; }
        return Verdict.Malformed;
    }
}
```

Each message type has its own bucket, so a chat spammer cannot use up the allowance for movement messages, and a bucket allows a short burst but not a sustained flood. The schema check rejects unknown or missing fields, wrong types, NaN or infinite numbers and out-of-range values before any game code reads the payload; strikes decay so one glitchy client is not removed, but sustained abuse is.

**Plan**
- The server calls `Record(playerId, position, serverTime)` every network tick, keeping 1 second of history per player and a hitbox object per player; `ClearHistory` is called after server teleports so nobody is rewound across one.
- `TryHit(shooter, clientTime, serverNow, origin, direction)` rejects timestamps in the future or malformed directions, clamps the rewind to `serverNow - maxRewindSeconds` (the ping limit), and rejects an origin that is not near the shooter's own rewound position.
- It then moves every other player's hitbox to its interpolated position at that time, raycasts the world first (walls block), then the hitboxes up to the wall distance, and returns the victim id or a rejection reason.

```csharp
using System.Collections.Generic;
using UnityEngine;

public class LagCompensatedHits : MonoBehaviour
{
    private struct Snapshot
    {
        public double Time;
        public Vector3 Position;
    }

    private class Tracked
    {
        public readonly List<Snapshot> History = new List<Snapshot>();
        public GameObject Hitbox;
    }

    [SerializeField] private float historySeconds = 1f;
    [SerializeField] private float maxRewindSeconds = 0.25f;
    [SerializeField] private float futureTolerance = 0.05f;
    [SerializeField] private float eyeHeight = 1.6f;
    [SerializeField] private float maxOriginError = 1.5f;
    [SerializeField] private float range = 200f;
    [SerializeField] private Vector3 hitboxSize = new Vector3(0.7f, 1.8f, 0.7f);
    [SerializeField] private int hitboxLayer = 31;
    [SerializeField] private LayerMask worldMask = ~0;

    private readonly Dictionary<ulong, Tracked> players = new Dictionary<ulong, Tracked>();
    private readonly Dictionary<Collider, ulong> owners = new Dictionary<Collider, ulong>();

    public void Record(ulong playerId, Vector3 position, double serverTime)
    {
        Tracked tracked;
        if (!players.TryGetValue(playerId, out tracked))
        {
            tracked = new Tracked();
            tracked.Hitbox = GameObject.CreatePrimitive(PrimitiveType.Cube);
            tracked.Hitbox.name = "LagHitbox_" + playerId;
            tracked.Hitbox.layer = hitboxLayer;
            tracked.Hitbox.transform.localScale = hitboxSize;
            Destroy(tracked.Hitbox.GetComponent<Renderer>());
            owners[tracked.Hitbox.GetComponent<Collider>()] = playerId;
            players[playerId] = tracked;
        }
        tracked.History.Add(new Snapshot { Time = serverTime, Position = position });
        while (tracked.History.Count > 1 && tracked.History[0].Time < serverTime - historySeconds) tracked.History.RemoveAt(0);
    }

    public void ClearHistory(ulong playerId)
    {
        Tracked tracked;
        if (players.TryGetValue(playerId, out tracked) && tracked.History.Count > 0)
        {
            Snapshot last = tracked.History[tracked.History.Count - 1];
            tracked.History.Clear();
            tracked.History.Add(last);
        }
    }

    public void Remove(ulong playerId)
    {
        Tracked tracked;
        if (!players.TryGetValue(playerId, out tracked)) return;
        owners.Remove(tracked.Hitbox.GetComponent<Collider>());
        Destroy(tracked.Hitbox);
        players.Remove(playerId);
    }

    public bool TryHit(ulong shooter, double clientTime, double serverNow, Vector3 origin, Vector3 direction, out ulong victim, out string reason)
    {
        victim = 0;
        Tracked self;
        if (!players.TryGetValue(shooter, out self)) { reason = "unknown shooter"; return false; }
        if (clientTime > serverNow + futureTolerance) { reason = "timestamp in the future"; return false; }
        if (direction.sqrMagnitude < 0.9f || direction.sqrMagnitude > 1.1f || float.IsNaN(direction.x + direction.y + direction.z)) { reason = "bad direction"; return false; }

        double rewindTo = System.Math.Max(serverNow - maxRewindSeconds, System.Math.Min(clientTime, serverNow));
        Vector3 shooterPosition = PositionAt(self, rewindTo);
        if (Vector3.Distance(origin, shooterPosition + Vector3.up * eyeHeight) > maxOriginError) { reason = "origin too far from shooter"; return false; }

        foreach (KeyValuePair<ulong, Tracked> pair in players)
        {
            bool active = pair.Key != shooter && pair.Value.History.Count > 0;
            pair.Value.Hitbox.SetActive(active);
            if (active) pair.Value.Hitbox.transform.position = PositionAt(pair.Value, rewindTo) + Vector3.up * hitboxSize.y * 0.5f;
        }
        Physics.SyncTransforms();

        float limit = range;
        RaycastHit hit;
        if (Physics.Raycast(origin, direction, out hit, range, worldMask, QueryTriggerInteraction.Ignore)) limit = hit.distance;
        ulong found;
        if (Physics.Raycast(origin, direction, out hit, limit, 1 << hitboxLayer, QueryTriggerInteraction.Ignore) && owners.TryGetValue(hit.collider, out found))
        {
            victim = found;
            reason = null;
            return true;
        }
        reason = "no hit";
        return false;
    }

    private static Vector3 PositionAt(Tracked tracked, double time)
    {
        List<Snapshot> h = tracked.History;
        if (h.Count == 0) return Vector3.zero;
        if (time <= h[0].Time) return h[0].Position;
        for (int i = 1; i < h.Count; i++)
        {
            if (h[i].Time >= time)
            {
                float t = (float)((time - h[i - 1].Time) / System.Math.Max(h[i].Time - h[i - 1].Time, 0.0001));
                return Vector3.Lerp(h[i - 1].Position, h[i].Position, Mathf.Clamp01(t));
            }
        }
        return h[h.Count - 1].Position;
    }
}
```

The server rewinds only the targets, and only as far as `maxRewindSeconds`, so a client claiming an old timestamp cannot shoot at where players were seconds ago, and a client with real lag still gets credit for what it saw. Hits are decided by the server's own raycast against recorded server positions, with walls taking priority, so a client can only choose when and where to aim.

**Plan**
- `BanManager` loads `bans.json` from `Application.persistentDataPath` into a dictionary keyed by account id (for example a SteamID string), dropping expired entries.
- `Ban` stores reason, evidence and an expiry (0 = permanent) and saves the file by writing a temporary file and then replacing the real one; `Unban` removes a record.
- `CheckOnConnect(accountId, out message)` is called by the server when a player connects: it returns false with the ban message while a ban is active, and expired bans are cleaned up as they are seen.

```csharp
using System;
using System.Collections.Generic;
using UnityEngine;

public class BanManager : MonoBehaviour
{
    [Serializable]
    public class BanRecord
    {
        public string accountId;
        public string reason;
        public string evidence;
        public long createdAt;
        public long expiresAt;
    }

    [Serializable]
    private class BanFile
    {
        public List<BanRecord> bans = new List<BanRecord>();
    }

    [SerializeField] private string fileName = "bans.json";

    private readonly Dictionary<string, BanRecord> bans = new Dictionary<string, BanRecord>();
    private string filePath;

    public event Action<string, string> OnBanned;

    private void Awake()
    {
        filePath = System.IO.Path.Combine(Application.persistentDataPath, fileName);
        Load();
    }

    public bool CheckOnConnect(string accountId, out string message)
    {
        BanRecord record;
        if (IsBanned(accountId, out record))
        {
            message = record.expiresAt == 0
                ? "Banned permanently: " + record.reason
                : "Banned until " + DateTimeOffset.FromUnixTimeSeconds(record.expiresAt).ToString("u") + ": " + record.reason;
            return false;
        }
        message = null;
        return true;
    }

    public bool IsBanned(string accountId, out BanRecord record)
    {
        if (string.IsNullOrEmpty(accountId) || !bans.TryGetValue(accountId, out record)) { record = null; return false; }
        if (record.expiresAt != 0 && record.expiresAt <= Now())
        {
            bans.Remove(accountId);
            Save();
            record = null;
            return false;
        }
        return true;
    }

    public void Ban(string accountId, string reason, string evidence, double durationSeconds = 0)
    {
        if (string.IsNullOrEmpty(accountId)) return;
        long now = Now();
        bans[accountId] = new BanRecord
        {
            accountId = accountId,
            reason = reason,
            evidence = evidence,
            createdAt = now,
            expiresAt = durationSeconds > 0 ? now + (long)durationSeconds : 0
        };
        Save();
        Debug.LogWarning("[BanManager] banned " + accountId + ": " + reason);
        if (OnBanned != null) OnBanned(accountId, reason);
    }

    public bool Unban(string accountId)
    {
        bool removed = bans.Remove(accountId);
        if (removed) Save();
        return removed;
    }

    private static long Now()
    {
        return DateTimeOffset.UtcNow.ToUnixTimeSeconds();
    }

    private void Load()
    {
        bans.Clear();
        if (!System.IO.File.Exists(filePath)) return;
        try
        {
            BanFile file = JsonUtility.FromJson<BanFile>(System.IO.File.ReadAllText(filePath));
            if (file == null) return;
            long now = Now();
            foreach (BanRecord record in file.bans)
                if (record.expiresAt == 0 || record.expiresAt > now) bans[record.accountId] = record;
        }
        catch (Exception e)
        {
            Debug.LogError("[BanManager] could not read " + filePath + ": " + e.Message);
        }
    }

    private void Save()
    {
        BanFile file = new BanFile();
        file.bans.AddRange(bans.Values);
        string temp = filePath + ".tmp";
        try
        {
            System.IO.File.WriteAllText(temp, JsonUtility.ToJson(file, true));
            if (System.IO.File.Exists(filePath)) System.IO.File.Replace(temp, filePath, null);
            else System.IO.File.Move(temp, filePath);
        }
        catch (Exception e)
        {
            Debug.LogError("[BanManager] could not save bans: " + e.Message);
        }
    }
}
```

Bans are keyed by the platform account id the server gets from the authentication ticket (never a client-supplied name), so changing a display name does not evade one. Writing a temporary file and then replacing the real one means a crash during a save cannot leave a half-written ban list. This file uses fully qualified `System.IO` calls because file access is required, which is outside the usual namespace list.

**Plan**
- `StrikeSystem.Report(playerId, detection, points, evidence, blatant)` decays the player's score (default 1 point per minute), adds the points, writes a log entry with the evidence, and returns the action taken.
- The ladder is warn at 2, correct (rubber-band) at 4, kick at 7 and ban at 10, or immediately on a blatant detection; each step raises its own event for the game to act on.
- `shadowMode` records and returns what would have happened without raising events, so thresholds can be tested on real traffic first.

```csharp
using System;
using System.Collections.Generic;
using UnityEngine;

public class StrikeSystem : MonoBehaviour
{
    public enum Action { Logged, Warn, Correct, Kick, Ban }

    private class Score
    {
        public float Value;
        public double Updated;
    }

    [SerializeField] private float warnAt = 2f;
    [SerializeField] private float correctAt = 4f;
    [SerializeField] private float kickAt = 7f;
    [SerializeField] private float banAt = 10f;
    [SerializeField] private float decayPerMinute = 1f;
    [SerializeField] private int logLimit = 500;
    [SerializeField] private bool shadowMode;

    private readonly Dictionary<ulong, Score> scores = new Dictionary<ulong, Score>();
    private readonly List<string> log = new List<string>();

    public event System.Action<ulong, string> OnWarn;
    public event System.Action<ulong, string> OnCorrect;
    public event System.Action<ulong, string> OnKick;
    public event System.Action<ulong, string> OnBan;

    public IList<string> Log { get { return log.AsReadOnly(); } }

    public Action Report(ulong playerId, string detection, float points, string evidence, bool blatant = false)
    {
        double now = Time.realtimeSinceStartupAsDouble;
        Score score;
        if (!scores.TryGetValue(playerId, out score))
        {
            score = new Score { Updated = now };
            scores[playerId] = score;
        }
        score.Value = Mathf.Max(0f, score.Value - (float)(now - score.Updated) / 60f * decayPerMinute) + points;
        score.Updated = now;

        Action action = Action.Logged;
        if (blatant || score.Value >= banAt) action = Action.Ban;
        else if (score.Value >= kickAt) action = Action.Kick;
        else if (score.Value >= correctAt) action = Action.Correct;
        else if (score.Value >= warnAt) action = Action.Warn;

        string entry = string.Format("{0:u} player {1} {2} +{3:0.0} => {4:0.0} [{5}]{6} | {7}",
            DateTime.UtcNow, playerId, detection, points, score.Value, action, blatant ? " BLATANT" : "", evidence);
        log.Add(entry);
        if (log.Count > logLimit) log.RemoveAt(0);
        Debug.LogWarning("[StrikeSystem] " + entry);

        if (shadowMode) return action;
        switch (action)
        {
            case Action.Warn: if (OnWarn != null) OnWarn(playerId, detection); break;
            case Action.Correct: if (OnCorrect != null) OnCorrect(playerId, detection); break;
            case Action.Kick: if (OnKick != null) OnKick(playerId, detection); break;
            case Action.Ban: if (OnBan != null) OnBan(playerId, BuildEvidence(playerId)); break;
        }
        return action;
    }

    public float GetScore(ulong playerId)
    {
        Score score;
        return scores.TryGetValue(playerId, out score) ? score.Value : 0f;
    }

    public void Clear(ulong playerId)
    {
        scores.Remove(playerId);
    }

    private string BuildEvidence(ulong playerId)
    {
        List<string> mine = new List<string>();
        string marker = "player " + playerId + " ";
        foreach (string line in log)
            if (line.Contains(marker)) mine.Add(line);
        return string.Join("\n", mine.ToArray());
    }
}
```

Every detector calls the same `Report` method with a point value that matches how certain it is (a small value for something lag could cause, a blatant flag for an impossible event), so the whole game shares one escalation policy and one evidence log. The decay means isolated false positives fade away, and the ban event hands over every logged line for that player so a moderator can review it.

**Plan**
- `ObscuredInt` stores a value XOR a random key that changes on every write, plus a checksum, so searching memory for the displayed number finds nothing and a changed field is detected on the next read.
- `ClientTamperGuard` keeps coins and health in `ObscuredInt` and raises `OnTamperDetected` if a checksum fails, and compares elapsed `Time.realtimeSinceStartup` with elapsed `DateTime.UtcNow` once per second; a sustained ratio far from 1 suggests a speed hack.
- The comments state plainly that these checks are only a deterrent that raises the effort needed; the server must still own the real values.

```csharp
using System;
using UnityEngine;

// CLIENT-SIDE DETERRENTS ONLY. A cheater controls the client, so every check here can be patched out.
// They only raise the cost of casual memory editing. The real protection is server-side:
// the server owns currency, health, inventory and results and ignores values sent by clients.
[Serializable]
public struct ObscuredInt
{
    [SerializeField] private int hidden;
    [SerializeField] private int key;
    [SerializeField] private int check;

    public ObscuredInt(int value)
    {
        key = UnityEngine.Random.Range(1, int.MaxValue);
        hidden = value ^ key;
        check = Checksum(value, key);
    }

    public int Value
    {
        get { return hidden ^ key; }
        set
        {
            key = UnityEngine.Random.Range(1, int.MaxValue);
            hidden = value ^ key;
            check = Checksum(value, key);
        }
    }

    public bool IsTampered { get { return Checksum(hidden ^ key, key) != check; } }

    private static int Checksum(int value, int salt)
    {
        unchecked { return (value * 31) ^ (salt * 17) ^ 0x5bd1e995; }
    }
}

public class ClientTamperGuard : MonoBehaviour
{
    [SerializeField] private float driftWindowSeconds = 1f;
    [SerializeField] private float allowedRatio = 0.15f;
    [SerializeField] private int strikesBeforeReport = 3;

    private ObscuredInt coins = new ObscuredInt(0);
    private ObscuredInt health = new ObscuredInt(100);
    private double lastRealtime;
    private DateTime lastUtc;
    private int driftStrikes;

    public event Action<string> OnTamperDetected;

    public int Coins { get { return coins.Value; } }
    public int Health { get { return health.Value; } }

    // For display only: the server's value is the real one and overwrites this whenever it arrives.
    public void SetFromServer(int serverCoins, int serverHealth)
    {
        coins.Value = serverCoins;
        health.Value = serverHealth;
    }

    private void Start()
    {
        lastRealtime = Time.realtimeSinceStartupAsDouble;
        lastUtc = DateTime.UtcNow;
        InvokeRepeating("CheckValues", 1f, 1f);
        InvokeRepeating("CheckClockDrift", driftWindowSeconds, driftWindowSeconds);
    }

    private void CheckValues()
    {
        if (coins.IsTampered) Report("currency value changed in memory");
        if (health.IsTampered) Report("health value changed in memory");
    }

    private void CheckClockDrift()
    {
        double realtime = Time.realtimeSinceStartupAsDouble;
        DateTime utc = DateTime.UtcNow;
        double gameDelta = realtime - lastRealtime;
        double wallDelta = (utc - lastUtc).TotalSeconds;
        lastRealtime = realtime;
        lastUtc = utc;

        // A large wall-clock gap means the app was suspended or the clock was changed; skip that window.
        if (wallDelta <= 0.0 || wallDelta > driftWindowSeconds * 5.0) { driftStrikes = 0; return; }
        double ratio = gameDelta / wallDelta;
        if (Math.Abs(ratio - 1.0) > allowedRatio) driftStrikes++;
        else driftStrikes = Math.Max(0, driftStrikes - 1);
        if (driftStrikes >= strikesBeforeReport)
        {
            driftStrikes = 0;
            Report(string.Format("game clock runs at {0:0.00}x of the system clock", ratio));
        }
    }

    private void Report(string reason)
    {
        Debug.LogWarning("[ClientTamperGuard] " + reason);
        if (OnTamperDetected != null) OnTamperDetected(reason);
    }
}
```

The report is meant to be sent to the server as a hint to look closer, never as proof, because a modified client can simply not send it. A new random key on every write defeats the "search for the number, change it, search again" memory scanners, and the drift check ignores long gaps so a suspended phone or a changed system clock does not trigger it.

**Plan**
- `ServerEconomy` holds balances in a private dictionary; `TryAdd(playerId, amount, reason, now)` is the only way to gain currency and `TrySpend` the only way to lose it, and both reject non-positive amounts and unknown reasons.
- Every reason has a maximum income per minute and there is an overall maximum; the economy keeps a 60-second window of grants and, if a grant would push a total over a cap (with a tolerance), it is rolled back (not applied), logged with evidence and counted as a flag.
- `OnFlag` and `OnKick` events let the game react; 3 flags in a row raise `OnKick`, and flags decay with time.

```csharp
using System;
using System.Collections.Generic;
using UnityEngine;

public class ServerEconomy : MonoBehaviour
{
    [Serializable]
    public struct Source
    {
        public string reason;
        public long maxPerMinute;
    }

    private struct Grant
    {
        public double Time;
        public long Amount;
        public string Reason;
    }

    [SerializeField] private Source[] sources = { new Source { reason = "quest", maxPerMinute = 1500 }, new Source { reason = "kill", maxPerMinute = 800 }, new Source { reason = "sale", maxPerMinute = 2500 } };
    [SerializeField] private long globalMaxPerMinute = 3000;
    [SerializeField] private float tolerance = 1.2f;
    [SerializeField] private float windowSeconds = 60f;
    [SerializeField] private int kickFlags = 3;
    [SerializeField] private float flagDecayMinutes = 5f;

    private readonly Dictionary<ulong, long> balances = new Dictionary<ulong, long>();
    private readonly Dictionary<ulong, List<Grant>> windows = new Dictionary<ulong, List<Grant>>();
    private readonly Dictionary<ulong, int> flags = new Dictionary<ulong, int>();
    private readonly Dictionary<ulong, double> lastFlag = new Dictionary<ulong, double>();
    private readonly List<string> evidenceLog = new List<string>();

    public event Action<ulong, string> OnFlag;
    public event Action<ulong> OnKick;

    public void Load(ulong playerId, long balance)
    {
        balances[playerId] = Math.Max(0L, balance);
        windows[playerId] = new List<Grant>();
    }

    public long Get(ulong playerId)
    {
        long balance;
        return balances.TryGetValue(playerId, out balance) ? balance : 0L;
    }

    public bool TryAdd(ulong playerId, long amount, string reason, double now)
    {
        long limit = LimitFor(reason);
        if (!balances.ContainsKey(playerId) || limit <= 0 || amount <= 0 || amount > globalMaxPerMinute)
        {
            Flag(playerId, now, string.Format("rejected add {0} for '{1}'", amount, reason));
            return false;
        }

        List<Grant> window = windows[playerId];
        window.RemoveAll(g => now - g.Time > windowSeconds);
        long total = amount, forReason = amount;
        foreach (Grant g in window)
        {
            total += g.Amount;
            if (g.Reason == reason) forReason += g.Amount;
        }
        if (forReason > limit * tolerance || total > globalMaxPerMinute * tolerance)
        {
            Flag(playerId, now, string.Format("rolled back +{0} '{1}': {2} for this reason (cap {3}), {4} total (cap {5}) in {6}s",
                amount, reason, forReason, limit, total, globalMaxPerMinute, windowSeconds));
            return false;
        }
        window.Add(new Grant { Time = now, Amount = amount, Reason = reason });
        balances[playerId] += amount;
        return true;
    }

    public bool TrySpend(ulong playerId, long amount, string reason)
    {
        long balance;
        if (amount <= 0 || !balances.TryGetValue(playerId, out balance) || balance < amount) return false;
        balances[playerId] = balance - amount;
        return true;
    }

    public void Remove(ulong playerId)
    {
        balances.Remove(playerId);
        windows.Remove(playerId);
        flags.Remove(playerId);
        lastFlag.Remove(playerId);
    }

    private long LimitFor(string reason)
    {
        foreach (Source s in sources)
            if (s.reason == reason) return s.maxPerMinute;
        return 0;
    }

    private void Flag(ulong playerId, double now, string evidence)
    {
        int count;
        flags.TryGetValue(playerId, out count);
        double last;
        if (lastFlag.TryGetValue(playerId, out last) && now - last > flagDecayMinutes * 60.0) count = 0;
        flags[playerId] = ++count;
        lastFlag[playerId] = now;
        string line = string.Format("{0:u} player {1} flag {2}: {3} (balance {4})", DateTime.UtcNow, playerId, count, evidence, Get(playerId));
        evidenceLog.Add(line);
        Debug.LogWarning("[ServerEconomy] " + line);
        if (OnFlag != null) OnFlag(playerId, evidence);
        if (count >= kickFlags && OnKick != null) OnKick(playerId);
    }
}
```

Currency has one entry point with a reason, so an impossible rate shows up as a number in the window: a legitimate source can only produce its own `maxPerMinute`, so a replayed or spammed reward message is refused before it touches the balance, which is the rollback. Pass the server's time for `now`, never a client timestamp.

**Plan**
- `VrPoseValidator.Validate(playerId, head, left, right, bodyRoot, serverTime)` receives the three tracked positions and the server's own body/locomotion position.
- It rejects a head too far from the body root or at an impossible height, hands farther than arm reach from the estimated shoulders, hand speed above a realistic limit (using the previous frame and a lag-tolerant speed budget), and a head that sweeps through walls (`SphereCast` against `wallMask`).
- A rejection returns the last valid pose as the correction and adds a decaying strike (kick and ban events at higher counts); teleport locomotion is whitelisted with `AllowTeleport`.

```csharp
using System;
using System.Collections.Generic;
using UnityEngine;

public struct VrPose
{
    public Vector3 Head;
    public Vector3 Left;
    public Vector3 Right;
}

public struct VrResult
{
    public bool Valid;
    public VrPose Correction;
    public string Reason;
}

public class VrPoseValidator : MonoBehaviour
{
    private class State
    {
        public VrPose Last;
        public double LastTime;
        public float HandDebt;
        public float Strikes;
        public double Updated;
        public double TeleportUntil;
    }

    [SerializeField] private LayerMask wallMask = ~0;
    [SerializeField] private float maxHeadOffsetFromBody = 1.6f;
    [SerializeField] private float minHeadHeight = 0.25f;
    [SerializeField] private float maxHeadHeight = 2.4f;
    [SerializeField] private float shoulderDrop = 0.25f;
    [SerializeField] private float armReach = 1.0f;
    [SerializeField] private float maxHandSpeed = 14f;
    [SerializeField] private float handDebtLimit = 2f;
    [SerializeField] private float headRadius = 0.15f;
    [SerializeField] private float decayPerMinute = 1f;
    [SerializeField] private float kickStrikes = 6f;
    [SerializeField] private float banStrikes = 10f;
    [SerializeField] private bool enforce = true;

    private readonly Dictionary<ulong, State> states = new Dictionary<ulong, State>();

    public event Action<ulong> OnKick;
    public event Action<ulong, string> OnBan;

    public void AllowTeleport(ulong playerId, double serverTime, double seconds = 1.0)
    {
        State state;
        if (states.TryGetValue(playerId, out state)) state.TeleportUntil = serverTime + seconds;
    }

    public VrResult Validate(ulong playerId, VrPose pose, Vector3 bodyRoot, double serverTime)
    {
        State state;
        if (!states.TryGetValue(playerId, out state))
        {
            states[playerId] = new State { Last = pose, LastTime = serverTime, Updated = serverTime };
            return new VrResult { Valid = true, Correction = pose };
        }

        string reason = null;
        Vector3 offset = pose.Head - bodyRoot;
        float height = offset.y;
        if (new Vector3(offset.x, 0f, offset.z).magnitude > maxHeadOffsetFromBody) reason = "head too far from body";
        else if (height < minHeadHeight || height > maxHeadHeight) reason = string.Format("head height {0:0.00}m", height);
        else
        {
            Vector3 shoulder = pose.Head - Vector3.up * shoulderDrop;
            float leftReach = Vector3.Distance(pose.Left, shoulder);
            float rightReach = Vector3.Distance(pose.Right, shoulder);
            if (leftReach > armReach || rightReach > armReach) reason = string.Format("hand reach {0:0.00}/{1:0.00}m, max {2:0.00}m", leftReach, rightReach, armReach);
        }

        bool teleporting = serverTime <= state.TeleportUntil;
        if (reason == null && !teleporting)
        {
            float dt = Mathf.Clamp((float)(serverTime - state.LastTime), 0.001f, 1f);
            float fastest = Mathf.Max(Vector3.Distance(pose.Left, state.Last.Left), Vector3.Distance(pose.Right, state.Last.Right));
            state.HandDebt = Mathf.Max(0f, state.HandDebt + fastest - maxHandSpeed * dt);
            if (state.HandDebt > handDebtLimit) reason = string.Format("hand speed {0:0.0}m/s, max {1:0.0}", fastest / dt, maxHandSpeed);
            else
            {
                Vector3 step = pose.Head - state.Last.Head;
                RaycastHit hit;
                if (step.magnitude > 0.001f && Physics.SphereCast(state.Last.Head, headRadius, step.normalized, out hit, step.magnitude, wallMask, QueryTriggerInteraction.Ignore))
                    reason = "head passed through " + hit.collider.name;
            }
        }

        state.LastTime = serverTime;
        if (reason == null)
        {
            state.Last = pose;
            return new VrResult { Valid = true, Correction = pose };
        }
        state.HandDebt = 0f;
        AddStrike(playerId, state, serverTime, reason);
        return new VrResult { Valid = !enforce, Correction = enforce ? state.Last : pose, Reason = reason };
    }

    private void AddStrike(ulong playerId, State state, double serverTime, string evidence)
    {
        state.Strikes = Mathf.Max(0f, state.Strikes - (float)(serverTime - state.Updated) / 60f * decayPerMinute) + 1f;
        state.Updated = serverTime;
        Debug.LogWarning(string.Format("[VrAC] player {0} strike {1:0.0}: {2}", playerId, state.Strikes, evidence));
        if (!enforce) return;
        if (state.Strikes >= banStrikes && OnBan != null) OnBan(playerId, "VR pose: " + evidence);
        else if (state.Strikes >= kickStrikes && OnKick != null) OnKick(playerId);
    }
}
```

The checks are anatomical limits with margins: a head cannot be far from the body that the server tracks, a hand cannot be farther than an arm from the shoulders, and hands move at human speeds. The speed uses a budget rather than a hard per-frame limit, so a dropped packet is forgiven, and a rejected pose returns the last valid pose to be applied to the avatar while the strike counts the repeats.

**Plan**
- `EvidenceRecorder` keeps a ring buffer of `seconds x recordHz` frames per player; each frame holds the server time, validated position, movement input and a button bitmask.
- Recording is a cheap array write with no allocation per frame once the buffer exists; frames are rate limited to `recordHz` per player.
- Any anti-cheat code calls the static `NotifyDetection(playerId, reason)`; the recorder writes the buffer in time order to `Evidence/<player>_<time>.json` under `persistentDataPath`, with the reason, so a moderator can replay what led to a ban.

```csharp
using System;
using System.Collections.Generic;
using UnityEngine;

public class EvidenceRecorder : MonoBehaviour
{
    [Serializable]
    public struct Frame
    {
        public double time;
        public Vector3 position;
        public Vector2 move;
        public uint buttons;
    }

    [Serializable]
    private class EvidenceFile
    {
        public string playerId;
        public string reason;
        public string savedAtUtc;
        public double detectionTime;
        public List<Frame> frames = new List<Frame>();
    }

    private class Ring
    {
        public Frame[] Frames;
        public int Next;
        public int Count;
        public double LastRecord;
    }

    [SerializeField] private float seconds = 10f;
    [SerializeField] private int recordHz = 20;
    [SerializeField] private string folderName = "Evidence";

    private readonly Dictionary<ulong, Ring> rings = new Dictionary<ulong, Ring>();

    public static event Action<ulong, string> Detected;

    // Call this from any detector when it flags a player.
    public static void NotifyDetection(ulong playerId, string reason)
    {
        if (Detected != null) Detected(playerId, reason);
    }

    private void OnEnable() { Detected += Dump; }
    private void OnDisable() { Detected -= Dump; }

    // Call with validated server-side data (after movement validation), not raw client claims.
    public void Record(ulong playerId, double serverTime, Vector3 position, Vector2 move, uint buttons)
    {
        Ring ring;
        if (!rings.TryGetValue(playerId, out ring))
        {
            ring = new Ring { Frames = new Frame[Mathf.Max(2, Mathf.CeilToInt(seconds * recordHz))], LastRecord = double.MinValue };
            rings[playerId] = ring;
        }
        if (serverTime - ring.LastRecord < 1.0 / recordHz) return;
        ring.LastRecord = serverTime;
        ring.Frames[ring.Next] = new Frame { time = serverTime, position = position, move = move, buttons = buttons };
        ring.Next = (ring.Next + 1) % ring.Frames.Length;
        ring.Count = Mathf.Min(ring.Count + 1, ring.Frames.Length);
    }

    public void Remove(ulong playerId)
    {
        rings.Remove(playerId);
    }

    public string Dump(ulong playerId, string reason)
    {
        Ring ring;
        if (!rings.TryGetValue(playerId, out ring) || ring.Count == 0) return null;

        EvidenceFile file = new EvidenceFile
        {
            playerId = playerId.ToString(),
            reason = reason,
            savedAtUtc = DateTime.UtcNow.ToString("o"),
            detectionTime = ring.Frames[(ring.Next - 1 + ring.Frames.Length) % ring.Frames.Length].time
        };
        int start = (ring.Next - ring.Count + ring.Frames.Length) % ring.Frames.Length;
        for (int i = 0; i < ring.Count; i++) file.frames.Add(ring.Frames[(start + i) % ring.Frames.Length]);

        try
        {
            string folder = System.IO.Path.Combine(Application.persistentDataPath, folderName);
            System.IO.Directory.CreateDirectory(folder);
            string path = System.IO.Path.Combine(folder, string.Format("{0}_{1:yyyyMMdd_HHmmss_fff}.json", playerId, DateTime.UtcNow));
            System.IO.File.WriteAllText(path, JsonUtility.ToJson(file, true));
            Debug.LogWarning("[Evidence] saved " + ring.Count + " frames to " + path + " (" + reason + ")");
            return path;
        }
        catch (Exception e)
        {
            Debug.LogError("[Evidence] could not save evidence for " + playerId + ": " + e.Message);
            return null;
        }
    }
}
```

The ring buffer overwrites the oldest frame, so memory use is fixed no matter how long a match lasts, and the file is only written when something is flagged. Recording validated positions rather than raw client claims shows what the server accepted, and the saved frames are in time order so they can be replayed or plotted. This file uses fully qualified `System.IO` calls because writing a file requires them, which is outside the usual namespace list.

**Plan**
- Design: the server is authoritative for position, health, currency, inventory and results; clients send only inputs and intent, and every check runs on the server with real timestamps. Lag compensation is limited to a clamped rewind, and lag itself is handled with leaky budgets and tolerances so honest players are not flagged.
- False positives are avoided by exempting server teleports and boosts, capping lag credit, and making the first reaction a rubber-band; strikes decay and only repeats or blatant violations kick or ban.
- Shadow mode reports what would have happened without acting, and every detection is stored as evidence (the last log lines per player go with the ban event).
- `AntiCheatServer` ties movement validation, per-message rate limiting, strikes and bans together.

```csharp
using System;
using System.Collections.Generic;
using UnityEngine;

// DESIGN
// Authority: the server owns position, health, currency, inventory and match results; clients send inputs only.
// Never trust: client timestamps (clamp them), client-reported positions (validate), client-side checks (cosmetic only).
// Lag: speed is a leaky budget over real elapsed time (capped lag credit), so a hitch is forgiven and sustained speed is not.
// Legit movement: the server calls MarkTeleport / GrantExemption before it moves a player on purpose.
// Rollout: shadowMode logs without acting; review the evidence, tune the numbers, then enforce. Rubber-band first, ban on repeats.
public class AntiCheatServer : MonoBehaviour
{
    private class Player
    {
        public Vector3 Last, Valid;
        public double LastTime, ExemptUntil, ScoreTime;
        public float Debt, Score;
        public readonly Dictionary<string, float> Tokens = new Dictionary<string, float>();
        public readonly Dictionary<string, double> TokenTime = new Dictionary<string, double>();
        public readonly List<string> Evidence = new List<string>();
    }

    [SerializeField] private float maxSpeed = 7f;
    [SerializeField] private float speedTolerance = 1.15f;
    [SerializeField] private float slackMetres = 0.75f;
    [SerializeField] private float debtLimit = 3f;
    [SerializeField] private float maxLagCreditSeconds = 1f;
    [SerializeField] private float teleportDistance = 25f;
    [SerializeField] private float messageRate = 10f;
    [SerializeField] private float messageBurst = 20f;
    [SerializeField] private float correctAt = 2f;
    [SerializeField] private float kickAt = 6f;
    [SerializeField] private float banAt = 10f;
    [SerializeField] private float decayPerMinute = 1f;
    [SerializeField] private bool shadowMode = true;

    private readonly Dictionary<ulong, Player> players = new Dictionary<ulong, Player>();

    public event Action<ulong, Vector3> OnCorrect;
    public event Action<ulong, string> OnKick;
    public event Action<ulong, string> OnBan;

    public void Connect(ulong id, Vector3 spawn, double now)
    {
        players[id] = new Player { Last = spawn, Valid = spawn, LastTime = now, ScoreTime = now };
    }

    public void Disconnect(ulong id) { players.Remove(id); }

    public void MarkTeleport(ulong id, Vector3 target, double now)
    {
        Player p;
        if (players.TryGetValue(id, out p)) { p.Last = target; p.Valid = target; p.LastTime = now; p.Debt = 0f; }
    }

    public void GrantExemption(ulong id, double now, double seconds)
    {
        Player p;
        if (players.TryGetValue(id, out p)) p.ExemptUntil = now + seconds;
    }

    // Returns the position the server should use for this player.
    public Vector3 ProcessMove(ulong id, Vector3 claimed, double now)
    {
        Player p;
        if (!players.TryGetValue(id, out p)) return claimed;
        float dt = Mathf.Clamp((float)(now - p.LastTime), 0.001f, maxLagCreditSeconds);
        Vector3 delta = claimed - p.Last;
        float flat = new Vector3(delta.x, 0f, delta.z).magnitude;
        p.LastTime = now;

        string problem = null;
        if (now < p.ExemptUntil) p.Debt = 0f;
        else if (delta.magnitude > teleportDistance) problem = string.Format("teleport {0:0.0}m in {1:0.00}s", delta.magnitude, dt);
        else
        {
            p.Debt = Mathf.Max(0f, p.Debt + flat - (maxSpeed * speedTolerance * dt + slackMetres));
            if (p.Debt > debtLimit) problem = string.Format("speed {0:0.0}m/s (limit {1:0.0})", flat / dt, maxSpeed * speedTolerance);
        }
        if (problem == null) { p.Last = claimed; p.Valid = claimed; return claimed; }

        p.Debt = 0f;
        Strike(id, p, now, 1.5f, "movement", problem + " at " + claimed);
        p.Last = shadowMode ? claimed : p.Valid;
        return shadowMode ? claimed : p.Valid;
    }

    // Per-player, per-message-type token bucket. Returns false when the message must be dropped.
    public bool AllowMessage(ulong id, string type, double now)
    {
        Player p;
        if (!players.TryGetValue(id, out p)) return false;
        float tokens;
        double last;
        if (!p.Tokens.TryGetValue(type, out tokens)) { tokens = messageBurst; last = now; } else last = p.TokenTime[type];
        tokens = Mathf.Min(messageBurst, tokens + (float)(now - last) * messageRate);
        p.TokenTime[type] = now;
        bool ok = tokens >= 1f;
        p.Tokens[type] = ok ? tokens - 1f : tokens;
        if (!ok) Strike(id, p, now, 0.25f, "flood", type);
        return ok;
    }

    public void Report(ulong id, string check, float points, string evidence, double now)
    {
        Player p;
        if (players.TryGetValue(id, out p)) Strike(id, p, now, points, check, evidence);
    }

    private void Strike(ulong id, Player p, double now, float points, string check, string evidence)
    {
        p.Score = Mathf.Max(0f, p.Score - (float)(now - p.ScoreTime) / 60f * decayPerMinute) + points;
        p.ScoreTime = now;
        string line = string.Format("{0:HH:mm:ss} {1} +{2:0.0} => {3:0.0}: {4}", DateTime.UtcNow, check, points, p.Score, evidence);
        p.Evidence.Add(line);
        if (p.Evidence.Count > 30) p.Evidence.RemoveAt(0);
        Debug.LogWarning(string.Format("[AntiCheat]{0} player {1} {2}", shadowMode ? "[SHADOW]" : "", id, line));
        if (shadowMode) return;

        if (p.Score >= banAt) { if (OnBan != null) OnBan(id, string.Join("\n", p.Evidence.ToArray())); }
        else if (p.Score >= kickAt) { if (OnKick != null) OnKick(id, check); }
        else if (p.Score >= correctAt && OnCorrect != null) OnCorrect(id, p.Valid);
    }
}
```

The design notes at the top are the short architecture document, and the class is the glue: `ProcessMove` is the single place every position update goes through, `AllowMessage` stops floods before any handler runs, and all detections feed one decaying score and one evidence list. Keep `shadowMode` on until the logs from real matches show no honest players being flagged.
